-- wave-nusa-dua-jimbaran-2026-10-08: 160 field(s) in one DO block, one UPDATE per column.
-- Each UPDATE must change exactly the number of rows it lists; if one does not, the whole block rolls back.
-- Generated 2026-10-08 by scripts/copy/build-copy-sql.mjs. Guards: md5 of the current text; every literal is ASCII.
do $apply$
declare n int;
begin
  update venues v set why_its_here = d.val
  from (values
    ('akua-mediterranean', '3e746cb25400ddb9a0e50f33fd5e0b75', 'A beachfront Mediterranean bar and restaurant on Jimbaran Beach, at Pemelisan Agung No. 27, formerly AKUA de Bilbao. The kitchen does Spanish tapas, mezze, handmade pastas, sourdough pizzas and grilled seafood from the bay, and the open terrace upstairs faces the sunset.'),
    ('arwana', '4e0d07bc59791e08ec8f53300d3ce684', 'The beachfront grill restaurant at The Laguna, a Luxury Collection Resort & Spa in Nusa Dua. Fresh seafood and dry-aged meats are cooked over Basque-style wood grills, alongside a Balinese menu. Tables are on a terrace beside the beach and the lagoon pools.'),
    ('ayana-fitness-centre', '79f4e048f7b8b001a4081127e3f689fa', 'The 24-hour gym on the AYANA estate above Jimbaran Bay. Steam and sauna rooms, a jacuzzi grotto, a cold plunge pool and an aerobics and yoga studio share its wellness complex. Personal trainers can be booked, and the grounds have lawn tennis and table tennis.'),
    ('azure-beach-restaurant', 'b7948740bb0e664f2bcb85ff2196c3d2', 'A beachfront Mediterranean restaurant with a pool on Kelan Beach, near Jimbaran. The seafood is locally sourced, and the chef is Frederic Boulay. There are daybeds, direct beach access and no cover charge.'),
    ('bali-barber-jimbaran', 'c7ac49345bc51ef872795c56417742cc', 'Bali Barber''s Jimbaran branch, part of the men''s grooming chain. You can walk in for a cut, a beard tidy or a hot-towel shave near the bay.'),
    ('balquisse-heritage-hotel-yoga-jimbaran', '0dc6211e625b0d6e7cb4de8dfbc1f001', 'Yoga classes in the garden of Balquisse Heritage Hotel, a boutique hotel in inner Jimbaran.'),
    ('balquisse-spa-jimbaran', '6c0b31d870c22c1437075165f07c9b81', 'The spa at Balquisse, a Moroccan-Balinese boutique heritage hotel in inner Jimbaran, where treatments take place in an intimate setting.'),
    ('bawang-merah-beachfront', '326990aebdac2ee7c79c8b84df979f91', U&'A beachfront seafood restaurant with tables on the sand at Kelan Beach, the quiet northern end of Jimbaran Bay. Whole fish, prawns, squid and lobster are charcoal-grilled and sold by weight. Balinese dancers perform nightly, around 7\20139pm, as the sun sets over the Indian Ocean.'),
    ('bejana-ritz-carlton', '4cec3f9c57f8c5df42cd7cf971f165f3', 'The Indonesian restaurant at The Ritz-Carlton, Bali, on the cliffs above the Indian Ocean at Sawangan, Nusa Dua. Regional Balinese and archipelago dishes are served across three levels, including the Culinary Cave open kitchen. The centrepiece is the Archipelago Rijsttafel, a shared multi-dish rice-table feast.'),
    ('brook-nusa-dua', '3ab1b3d8c0b4614c3093196841b1bc2c', 'A Benoa restaurant whose panoramic view takes in the airport runway as well as the Garuda statue and the ocean. The menu runs from American and European to Russian, Ukrainian and Asian dishes. It is styled like vintage Brooklyn and serves cocktails.'),
    ('bumbu-bali', 'caf9a0188a3f1578ead1f1c58b3ddd7b', 'A Balinese restaurant and cooking school on Nusa Dua''s northern edge, founded in 1996 by Swiss chef and cookbook author Heinz von Holzen. Home- and ceremony-style dishes such as babi guling and a multi-course rijsttafel are served in a traditional courtyard compound.'),
    ('camino-resto-and-bar', '643682cdd1be6529b0b8a7312745da95', 'A Mediterranean kitchen in Jimbaran built around a grill and a smoker. The menu has frutti di mare pasta, grilled fish and salmon, and there''s molten lava cake for dessert.'),
    ('canna-beach-club', '75ec8aa0babcd04fe051c4371be5c191', 'A large, multi-zone beachfront club on the southern side of Nusa Dua. It has a pool, daybeds, water sports and several dining areas, the oceanfront Cliff restaurant among them. It runs from daytime lounging into evening entertainment.'),
    ('club-med-bali-fitness', '68040126a38a5365c071e5c1d1400a90', 'The gym at the all-inclusive Club Med Bali, on the Nusa Dua ITDC estate, has a cardio room plus squash and tennis courts. Sport comes with the stay, coached by G.O. staff: padel, pickleball, archery, trapeze, plus aquafitness and water polo in the pool.'),
    ('conrad-bali-fitness-centre', '66aed75ca33cca1399194451f9cd8a2f', 'Conrad Bali''s 24-hour gym in Tanjung Benoa, inside the Jiwa Spa complex. The complex also holds 17 treatment rooms, garden pavilions, a steam room, a sauna and a jacuzzi. Pilates is on the class list, and the resort has two floodlit tennis courts.'),
    ('courtyard-by-marriott-nusa-dua-gym', '4f6f68a05893d412f6110edcbdd8daa2', U&'Courtyard by Marriott Bali Nusa Dua''s gym, with cardio and strength equipment, open to hotel guests 24 hours. Staff are on the floor 06:00\201323:00, with key access outside those hours. Instructor-led classes are free, and the resort also has a yoga pavilion and a spa.'),
    ('cuca-restaurant', 'a58d54f3ae784020b4f17b647502c663', 'A standalone Jimbaran restaurant opened in 2013 by chef Kevin Cherkas, formerly of elBulli, Arzak and Daniel. Its tapas are globally inspired and built on Indonesian ingredients; so are its cocktails and desserts.'),
    ('dava-steak-and-seafood', '279da032aff4fca8c77dbb5b00e4bf81', 'The AYANA Resort''s steakhouse and seafood grill, up on Jimbaran''s clifftop with ocean and sunset views. Dry-aged and wagyu beef and Canadian lobster go over a wood-fired grill. A beef sommelier and a salt-cart sommelier are on hand, and dinner starts in the Martini Bar.'),
    ('dua-kafe-nusa-dua', '6a1de1cc6aab292ab143851f8b2b2913', U&'An all-day caf\00E9 in Nusa Dua, a short walk from the beach. Drinks include a macadamia flat white and a matcha latte.'),
    ('fore-coffee-jimbaran', 'c1717b46e6703f9f6096e5368aac2af1', 'The Jimbaran branch of Fore, a specialty-coffee chain from Indonesia with several outlets in Bali. It pulls everyday espresso and palm-sugar (aren) lattes in a modern grab-and-go format.'),
    ('four-seasons-jimbaran-fitness-centre', '038f94596911899c89d9db2f62540c00', 'The gym at Four Seasons Resort Bali at Jimbaran Bay is fully equipped, and the aerobics studio has a sprung floor. Personal trainers give one-off advice or build a programme for a longer stay. There is also an oceanfront bale for training and practice.'),
    ('four-seasons-jimbaran-yoga', '4508e416130173437ac01117cba476bd', 'The yoga and meditation programme at Four Seasons Resort Bali at Jimbaran Bay, with daily classes in Yin, Kundalini and hot stone yoga. A local teacher runs Balinese sessions on Sekala and Niskala (the seen and unseen worlds). Classes also run on the beachfront.'),
    ('gourmet-and-cafe-nusa-dua', 'b8caa5c99e3c00b31866cad1d52a36dc', U&'A caf\00E9 in Nusa Dua serving food and health-forward drinks in a cosy, considered space.'),
    ('grand-hyatt-bali-yoga', '7c8bd3a18bde7116878169674c85b326', 'Grand Hyatt Bali runs daily yoga sessions from a dedicated studio in the Bay Club, and outdoors on the resort lawns. The lawns overlook the water lily pond, with the beach beyond.'),
    ('healing-village-spa-at-four-seasons-jimbaran-jimbaran', '3331e960a310c80ee0a684f76da41bab', 'The Healing Village Spa is on the hillside of Four Seasons Resort Bali at Jimbaran Bay, and its treatments are holistic and wellness-led.'),
    ('intercontinental-bali-resort-beauty-services-jimbaran', '3b75103acf3d3f68269b121da63ac5a9', 'The salon and beauty services at the InterContinental Bali Resort on Jimbaran Bay cover hair, nails and grooming, alongside the resort''s Spa Uluwatu.'),
    ('izakaya-by-oku', 'cd4a313ebd3b3b6431732c696cf1b2aa', 'The Apurva Kempinski Bali''s Japanese restaurant in Nusa Dua, an offshoot of OKU in Jakarta. Contemporary izakaya-style dishes come out of an open kitchen at the centre of a bistro room, so you can watch the chefs work.'),
    ('jimbaran-bay-beach-resort-spa-jimbaran', 'd26583a21538d4ec43fc50b528c00f1a', 'The spa at Jimbaran Bay Beach Resort near Kedonganan does Balinese massage and other treatments, steps from the sand.'),
    ('jimbaran-hair-beauty-studio', 'decbcc3ffe7221de66c6048f9cf53d49', 'A local hair-and-beauty studio in Jimbaran for cuts, colour, nails and waxing.'),
    ('karma-spa-at-karma-jimbaran-jimbaran', 'c50a4e2786af4f672f38a344c61e8729', 'Karma Spa at Karma Jimbaran, a beachside villa resort near Jimbaran Bay, runs treatments from 09:00 to 19:00.'),
    ('kayumanis-resto-jimbaran', '4ca3dcd570e52bdb1885ade3b19f4a35', 'The Indonesian restaurant of the Kayumanis Jimbaran Private Estate & Spa: a replica Javanese joglo, almost entirely hardwood, in a garden of coconut palms. Archipelago classics are built on market-fresh produce and catch-of-the-day seafood; betutu duck, beef ribs and charcoal-grilled prawns are among them.'),
    ('kayuputi', 'af734f7ac1eb55dcfc864c95c46209cb', 'The fine-dining restaurant at The St. Regis Bali Resort in Nusa Dua, in a white, open-kitchen room facing the Indian Ocean. Pan-Asian haute cuisine comes as multi-course degustation menus, backed by an extensive wine list, and there is a champagne brunch.'),
    ('kenja-ikan-bakar-nusa-dua', '2833208c3c51ae91ca0779b181b0e895', 'Ikan bakar and other grilled fish and shellfish are the speciality of this sit-down Indonesian restaurant on Jl. Pantai Mengiat. It is walkable from the Nusa Dua beach and ITDC area, with live music in the evening.'),
    ('koral', 'a9f58310d96b52888f306277913a7a2a', 'An aquarium restaurant inside The Apurva Kempinski Bali on Nusa Dua, where tables sit against large tanks holding 80-plus marine species. Degustation menus focus on seafood, drawing on Indonesian coastal flavours and local ingredients, with wine pairings and a cocktail station.'),
    ('kriya-spa-at-grand-hyatt-bali-nusa-dua', '20f193ae0b791179a05990b02a924240', 'Kriya Spa sits in the Grand Hyatt Bali''s water-palace-inspired grounds, with garden gazebos beside tropical pools. Its menu is organised around themed rituals (Bliss, Harmony, Purity, Energy) rooted in traditional Balinese and Javanese wellness.'),
    ('kubu-garden-restaurant', '1e9d87a582b3567fe85ec4778907a233', 'The all-day restaurant and coffee spot of Kubu Garden Suites, on Jl. Pratama in Tanjung Benoa. The kitchen cooks Indonesian, Western and Italian dishes, and the bread is baked in-house.'),
    ('manarai-beach-house', '1c266bca0d06d87239f93b3cad510daf', 'An ISMAYA beach club on the white-sand beachfront of the Sofitel Bali Nusa Dua Beach Resort. A restaurant leads through an outdoor lounge to two infinity pools and daybeds on the sand. Three bars, an all-day international and Balinese menu, and DJ sets at sunset.'),
    ('martha-tilaar-salon-day-spa-jimbaran', '0a3cef4bcfe28d167fda64a4fd489d21', 'A Jimbaran salon and day spa from Martha Tilaar, Indonesia''s homegrown beauty house. Traditional Javanese-Balinese rituals sit alongside everyday hair and nail services.'),
    ('mulia-fitness-centre-nusa-dua', '057a580945d30ff17266ddecb587a9f4', 'The Mulia''s resort gym on Geger beach is large and fully equipped, with cardio and weights. A movement studio runs group classes, and the racquet facilities include tennis and pickleball.'),
    ('mulia-spa-nusa-dua', 'ae46d88d374c46098a698ce2abb1b781', 'The Mulia''s 20-room spa, built around a hydrotherapy circuit that guests move through before a tailored, Ayurvedic-inspired treatment. The circuit takes in hot and cold plunge pools, Finnish saunas, steam and ice rooms, and Cleopatra-style hydrotonic pools with underwater jets.'),
    ('nusa-dua-beach-grill', 'e593ba2e28cc6ded52923b4d1572d836', 'An independent, family-run beachfront restaurant on the sand at Geger Beach, Nusa Dua, running since 1995. Grilled seafood (prawns, fish, lobster) shares the menu with Indonesian and Western dishes and pastas. Tables look over the calm turquoise Geger Lagoon, a short walk from The Mulia.'),
    ('nyoman-cafe', '14ee7bb124c91cae0af968ca519c5b3d', U&'Nyoman Caf\00E9 has been grilling seafood on the Jimbaran Bay sands, along the Muaya Beach strip, since 1994. You pick lobster, prawns, crab, snapper or squid from the tanks to be barbecued and served at candlelit tables on the beach.'),
    ('pantai-jimbaran', 'a4b97741bb4565487038485e7c45e22f', 'A curving bay south of the airport in Badung, with calm water, sunset views and beachfront seafood grills.'),
    ('piasan', '58f1e1fde30d4a7e3194071a0a0e4688', 'An Italian restaurant at Kayumanis Nusa Dua Private Villa & Spa, in a glass-and-bamboo room over manicured gardens. Homemade pasta and wood-fired pizza sit beside prime cuts. The Bistecca di Angus Nero alla Griglia is chargrilled Black Angus steak with risotto, portobello and red-wine sauce.'),
    ('piramid-spa', 'b08eda9bedcfec4581ca6369e3eaaf9e', 'A large Jimbaran day spa whose treatment huts are pyramid-shaped and stand over a koi pond. You can book Balinese massage, body scrubs or specialty treatments, and there is a cafe on site.'),
    ('radja-seafood-cafe', 'f13c0ae6f13d26358abec22325678af8', 'Radja is a beachfront seafood grill on Muaya Beach in Jimbaran Bay, with tables set out on the sand. You choose fish, prawns, clams or lobster from an iced display, and it goes on the charcoal grill. The sun sets over the bay.'),
    ('revi-vo-yoga-mindfulness-nusa-dua', '967c9771301f88585d3b2683f1537c85', U&'REV\012AV\014C Wellness Resort in Sawangan, Nusa Dua, runs its yoga and mindfulness programme in a dedicated yoga space and on an aerial-yoga deck. Guided meditation is part of its wellness retreats.'),
    ('signa-cafe', '22577d725abd79fd1055ca0223663059', 'A family runs this Benoa cafe on Jl. Raya Kampial, and breakfast is served all day. There''s coffee, plus gourmet pizza, pasta, wraps, desserts and cocktails. It also does delivery and takeaway.'),
    ('sofitel-bali-fitness-centre-nusa-dua', '1535916b1047e5e35312ba7093c85ea3', 'SoFIT is the beachfront gym at Sofitel Bali Nusa Dua Beach Resort, with cardio and strength equipment plus sauna and steam. Its class schedule runs from boxing and HIIT to aqua fitness.'),
    ('sofitel-bali-yoga', '2c4c264e13160e90d8e1f51beb780c7e', 'Sofitel Bali Nusa Dua runs yoga on Mondays, Thursdays and Sundays, at IDR 150,000++ per person for an hour. Private yoga and meditation cost extra, and so do Qi Gong and inner-power sessions. Beach yoga is on the resort activity list too.'),
    ('soleil-at-mulia', '59a63acab18d15a6904c7b326bcfcaa2', 'The beachfront restaurant at The Mulia, Mulia Resort & Villas in Nusa Dua, facing the Indian Ocean from indoor and terrace tables. Mediterranean and Pan-Asian dishes run from handcrafted pastas to grilled seafood. Sunday Brunch adds a seafood bar, live grill stations and Italian antipasti.'),
    ('st-regis-bali-athletic-club', '5c089f6f3ece505e35c7b6c4f6f38e5e', 'The St. Regis Bali Resort''s 24-hour gym sits inside its Iridium Spa in Nusa Dua. Life Fitness equipment is split into zones for strength, cardio and movement work, and personal trainers can be booked.'),
    ('sundara', '4bac0b711cc860ca6678cf0b1cdf6b18', U&'The beach club and beachfront restaurant at the Four Seasons Resort Bali at Jimbaran Bay. It steps down from a bar and daybeds to a 57-metre infinity pool and the sand. Seafood and charred meats are cooked over fire, and Sunday brings a ros\00E9 brunch.'),
    ('sunset-beach-bar-and-grill', 'eacdc020cc8c264a48165d1b8a3675e2', 'The InterContinental Bali Resort''s open-air beach bar on Jimbaran Bay, with your toes in the white sand among coconut palms. The view runs 180 degrees west over the water. Grilled dishes and cocktails come with live music every day as the sun goes down.'),
    ('tetaring', '6ded38afcd8002ec04feec4dcb18c3ec', 'A modern Indonesian restaurant at Kayumanis Nusa Dua Private Villa and Spa, named after a ceremonial roof structure of bamboo and palm fronds. Its glass-walled, bamboo-accented room serves archipelago dishes such as lemongrass Balinese chicken salad and black oxtail soup.'),
    ('the-apurva-kempinski-fitness-centre-nusa-dua', '26d0c79fe93acd5dc163407f70c13645', 'The Apurva Kempinski''s ocean-view resort gym, on the tiered clifftop, opens early and closes late. It has modern cardio and strength equipment, and trainers lead sessions.'),
    ('the-apurva-kempinski-yoga-nusa-dua', '10fc9c8b0eb7cb2cb00f75050d83a576', 'Yoga at The Apurva Kempinski means sunrise Hatha and flow classes on the beach, plus aerial anti-gravity yoga and sound-healing sessions. The resort''s clifftop and the ocean are the backdrop.'),
    ('the-apurva-spa-nusa-dua', '1909900a48802d34b76ed6b2356ce0f7', 'The Apurva Spa is part of The Apurva Kempinski, on the resort''s tiered clifftop above the Indian Ocean. Its treatments draw on traditional Balinese and Javanese healing: Lulur and Jamu rituals, sound healing and chakra work.'),
    ('the-bale-nusa-dua-yoga', 'c57fc46d0c007b113dbb104124d27bc3', U&'Private yoga rooms at The Bal\00E9 Nusa Dua, an adults-oriented retreat of 29 pavilions in Geger, each with its own pool. Yoga and pranayama are on the wellness menu with massage, energy treatments and detox programmes. There''s also a fitness centre and a quiet library.'),
    ('the-beach-grill-ritz-carlton', 'f5f77b2e099882c4fe811f393cba18bc', 'At The Ritz-Carlton, Bali in Nusa Dua, this beachfront grill faces the Indian Ocean from indoor and outdoor tables. Premium meats and locally sourced seafood, such as barramundi, snapper and king prawn, go into a Josper charcoal oven. The menu rotates monthly around seasonal ingredients.'),
    ('thermes-marins-bali-spa-at-ayana-jimbaran', '5abc790abb21e133ea86a180f18bb0bc', 'Thermes Marins Bali at AYANA Resort, a seawater-therapy destination spa on the Jimbaran clifftop with an Aquatonic pool.'),
    ('unique-rooftop-bar-and-restaurant', 'b84e0a045b97661886330204d38c7194', 'A two-level rooftop bar and pool club on top of RIMBA by AYANA in Jimbaran. Modern Mexican plates and tequila-led cocktails are served around a 25-metre infinity pool. The view takes in the Uluwatu hills and the Indian Ocean sunset.'),
    ('warung-dobiel-nusa-dua', 'e86e1e4fb84c8290c0c4141c97d401e3', 'A babi guling (Balinese suckling pork) warung in Bualu village, on Jl. Srikandi, a short trip from the Nusa Dua resort gates. It serves a pork plate and a rich pork soup, and there is often a queue before opening.'),
    ('warung-halme-ikan-bakar-ala-jimbaran', '33a3ffc536b808b6ee470506ee4f53bb', 'A casual warung grilling Jimbaran-style ikan bakar without the trip to Jimbaran itself. Prices are cheaper than on the Jimbaran beach seafood strip.'),
    ('warung-mami-ikan-bakar', 'b343ff99b454ac9f8b8f1d63117d2b00', 'Just three things go on the grill at this no-frills, family-run roadside seafood warung on Jalan Uluwatu II, Jimbaran: fish, prawns and clams. They come with three sambals plus free plecing kangkung and raw vegetables. On any day the catch isn''t fresh, it closes entirely.'),
    ('warung-nasi-ayam-bu-oki', '2dc2485774132278dbb0ae4193a285d2', 'A busy local nasi campur warung opposite Hotel Santika Siligita, in the Nusa Dua and Bualu area. The Balinese mixed-rice plates are cheap and built around chicken.'),
    ('warung-ramayana-ikan-bakar', '35d6e3bd096b438def2b023dd627a43b', 'This beachfront warung on Jimbaran Bay has served Jimbaran-style ikan bakar since around 1990. Fish and seafood are grilled over coconut husks and come with sambal, at tables on the sand facing the sunset.'),
    ('westin-nusa-dua-fitness-studio', '7b75add43899c75ad6001033bf71811b', 'The WestinWORKOUT studio at The Westin Resort Nusa Dua is open 24 hours. A rebuilt wellness floor, open since April 2026, adds reformer pilates, spin, a hot yoga sanctuary and a beachfront ice bath. Open-air beach workouts and outdoor HIIT run on the sand.'),
    ('westin-nusa-dua-yoga', '21fbec45fd8808ad9af88163111f8512', 'The Westin Resort Nusa Dua runs yoga from a hot yoga sanctuary added in April 2026, and as group sessions alongside pilates and spin. Ashtanga is on the schedule if you want a harder class.'),
    ('white-orchid-nusa-dua', '523b59ceae44efe8c955bf6a0541bb3d', 'A pan-Asian restaurant in the Bali Collection shopping-and-dining complex, in the BTDC resort area of Nusa Dua, open from breakfast through dinner. The menu runs to shareable Asian plates and satay grilled on a Balinese barbecue, and there are outdoor tables.')
  ) as d(slug, old_md5, val)
  where v.slug = d.slug and v.status = 'active' and v.publication_status = 'published'
    and case when d.old_md5 is null then (v.why_its_here is null or length(trim(v.why_its_here)) = 0) else md5(v.why_its_here) = d.old_md5 end;
  get diagnostics n = row_count; if n <> 70 then raise exception 'wave-nusa-dua-jimbaran-2026-10-08 why_its_here: expected 70 rows, got %', n; end if;

  update venues v set best_for = d.val
  from (values
    ('akua-mediterranean', '0523082b01d57503423bf81568574a26', 'Sunset drinks and shared plates by the sea, or a long, social seafood lunch with a group'),
    ('arkipela-spa-at-mo-venpick-jimbaran-jimbaran', '016ae0927c8831ba4294fda2d45db145', U&'A polished resort spa treatment near Samasta''s shops and caf\00E9s'),
    ('arwana', '3dfc9d736ceacce94fb13dd085be1d12', 'A seaside grill lunch or dinner with an ocean view, or the Sunday brunch, for resort guests and couples'),
    ('ayana-fitness-centre', 'd6d03997841ed764618adde29498881b', 'Guests on the AYANA estate who want a round-the-clock gym with sauna and cold plunge, and racquet sports on the same site'),
    ('azure-beach-restaurant', '8e9a7e12f20e4eb87922f36e93868293', 'Sunset seafood and an unhurried afternoon by the pool, or a last stop before an airport departure'),
    ('bali-barber-jimbaran', '70632320a8cd02e588416d6de843ba96', 'Men after a walk-in cut or shave near Jimbaran Bay'),
    ('bali-beauty-salon-nusa-dua', 'bd4559f109d4ac64c4e5a66e4e5cf963', 'Salon basics off-property while you''re in the resort area'),
    ('balquisse-heritage-hotel-yoga-jimbaran', '71ceac3ab1f8b53969d230c44eb8e9dd', 'Guests and neighbours after a quiet, small-group class off the tourist track'),
    ('balquisse-spa-jimbaran', '05c0dc53fecf3c8543489cd56f100ecd', 'A characterful, non-chain spa treatment away from the beach strip'),
    ('bawang-merah-beachfront', '3ed6ac644fa30742814cd5c10b5729c9', 'A sunset seafood dinner with your toes in the sand, for couples or groups staying clear of Jimbaran''s busier main strip'),
    ('bejana-ritz-carlton', '15bc8ada4072d5205c3edaca16b95d4a', 'An unhurried Indonesian dinner on a special evening, with cliff-top ocean views'),
    ('bumbu-bali', '08a2882dc07a360dee840e5f9cce1bfa', 'Trying a wide spread of traditional Balinese cooking over dinner, or taking a market-and-cooking class'),
    ('canna-beach-club', '7f3aa8137832b1d9ca7041968418913c', 'A full day-to-night outing for families or groups on Nusa Dua''s calm white-sand beach'),
    ('club-med-bali-fitness', '621971428adba554b7183e0466fa6656', 'Sport all day on one bill, from trapeze to padel, rather than a gym and nothing else'),
    ('conrad-bali-fitness-centre', '94431bccb72a5c3068b17bcc9da53ace', 'Nusa Dua and Tanjung Benoa guests who want a round-the-clock gym with spa, sauna and floodlit tennis on the same site'),
    ('courtyard-by-marriott-nusa-dua-gym', 'cf18eada8e08b975a5b181b361ad0e21', 'Free instructor-led classes on top of a 24-hour gym during a Nusa Dua stay'),
    ('cuca-restaurant', 'a47669633975579ac39547a878e7342b', 'Couples and groups after a tasting-style dinner of sharing plates, from BBQ octopus with Asian gazpacho to the Bali Breakfast dessert'),
    ('dava-steak-and-seafood', '4d7099e8755a4e1d23b5f7041e175b39', 'A special-occasion dinner for couples or steak-and-wine lovers who want an upscale grill with a sunset ocean backdrop'),
    ('dua-kafe-nusa-dua', 'c54088168ce858d7932d262fcfb0792a', 'A flat white or a matcha latte in Nusa Dua'),
    ('fore-coffee-jimbaran', '7f8181c4edb8e588e4ee9fe7929532e9', 'An affordable everyday coffee, or a quick aren latte on the go'),
    ('four-seasons-jimbaran-fitness-centre', '9720feedff5ff86e52fc6725dfdcb3c2', 'Resort guests who want a sprung aerobics floor and personal training rather than a room of machines'),
